<?php declare(strict_types=1);namespace App\Models;final class ToolRun extends Model{public function create(array $d):int{$this->db->execute('insert into tool_runs(user_id,ip,tool,input,output,score,created_at) values(?,?,?,?,?,?,now())',[$d['user_id'],$d['ip'],$d['tool'],$d['input'],$d['output'],$d['score']]);return (int)$this->db->id();}public function recent(?int $userId):array{return $this->db->all('select * from tool_runs where user_id <=> ? order by id desc limit 50',[$userId]);}public function usage(?int $userId,string $ip):int{$row=$this->db->fetch('select count(*) c from tool_runs where '.($userId?'user_id=?':'ip=?'),[$userId?:$ip]);return (int)($row['c']??0);}}
